-- Water points (120 FICTIONAL points in Ghana, EPSG:4326) for the GSH Workflows GeoSight videos.
-- Run in pgAdmin (Query Tool) or psql on your PostGIS database. Recreates public.water_points.

CREATE EXTENSION IF NOT EXISTS postgis;
DROP TABLE IF EXISTS public.water_points CASCADE;
CREATE TABLE public.water_points (id integer PRIMARY KEY, code text, name text, type text, status text, region_ucode text, region text, installed integer, geom geometry(Point,4326));
CREATE INDEX water_points_geom_gix ON public.water_points USING gist (geom);
ANALYZE public.water_points;
